[e2e-tester] maestro_cli tool call: run file-write --input-json {"path":"C:/Meastro/test-repos/crud/src/App.tsx","content":"import { useState, useEffect } from 'react'

interface User {
  id: number
  name: string
  email: string
}

const API_URL = 'http://localhost:3001'

function App() {
  const [users, setUsers] = useState<User[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [newName, setNewName] = useState('')
  const [newEmail, setNewEmail] = useState('')
  const [editingUser, setEditingUser] = useState<User | null>(null)
  const [editName, setEditName] = useState('')
  const [editEmail, setEditEmail] = useState('')

  useEffect(() => {
    fetchUsers()
  }, [])

  async function fetchUsers() {
    try {
      setLoading(true)
      const res = await fetch(`${API_URL}/api/users`)
      if (!res.ok) throw new Error('Failed to fetch users')
      setUsers(await res.json())
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error')
    } finally {
      setLoading(false)
    }
  }

  async function createUser(e: React.FormEvent) {
    e.preventDefault()
    if (!newName.trim() || !newEmail.trim()) return
    try {
      const res = await fetch(`${API_URL}/api/users`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: newName, email: newEmail }),
      })
      if (!res.ok) throw new Error('Failed to create user')
      setUsers(prev => [...prev, await res.json()])
      setNewName('')
      setNewEmail('')
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error')
    }
  }

  async function updateUser(e: React.FormEvent) {
    e.preventDefault()
    if (!editingUser || !editName.trim() || !editEmail.trim()) return
    try {
      const res = await fetch(`${API_URL}/api/users/${editingUser.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: editName, email: editEmail }),
      })
      if (!res.ok) throw new Error('Failed to update user')
      const updated = await res.json()
      setUsers(prev => prev.map(u => u.id === updated.id ? updated : u))
      setEditingUser(null)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error')
    }
  }

  async function deleteUser(id: number) {
    try {
      const res = await fetch(`${API_URL}/api/users/${id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to delete user')
      setUsers(prev => prev.filter(u => u.id !== id))
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error')
    }
  }

  function startEdit(user: User) {
    setEditingUser(user)
    setEditName(user.name)
    setEditEmail(user.email)
  }

  return (
    <div className="max-w-2xl mx-auto p-8">
      <h1 className="text-3xl font-bold mb-8">CRUD App — Users</h1>

      {error && (
        <div className="mb-4 p-3 bg-red-100 text-red-700 rounded flex justify-between">
          <span>{error}</span>
          <button className="underline" onClick={() => setError(null)}>Dismiss</button>
        </div>
      )}

      <form onSubmit={createUser} className="mb-8 p-4 border rounded bg-gray-50">
        <h2 className="text-lg font-semibold mb-3">Add User</h2>
        <div className="flex gap-2">
          <input
            className="flex-1 border rounded px-3 py-2"
            placeholder="Name"
            value={newName}
            onChange={e => setNewName(e.target.value)}
          />
          <input
            className="flex-1 border rounded px-3 py-2"
            placeholder="Email"
            value={newEmail}
            onChange={e => setNewEmail(e.target.value)}
          />
          <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">
            Add
          </button>
        </div>
      </form>

      {loading ? (
        <p className="text-gray-500">Loading...</p>
      ) : (
        <table className="w-full border-collapse">
          <thead>
            <tr className="bg-gray-100">
              <th className="text-left p-3 border">ID</th>
              <th className="text-left p-3 border">Name</th>
              <th className="text-left p-3 border">Email</th>
              <th className="text-left p-3 border">Actions</th>
            </tr>
          </thead>
          <tbody>
            {users.map(user => (
              <tr key={user.id} className="hover:bg-gray-50">
                <td className="p-3 border">{user.id}</td>
                <td className="p-3 border">{user.name}</td>
                <td className="p-3 border">{user.email}</td>
                <td className="p-3 border">
                  <button
                    onClick={() => startEdit(user)}
                    className="mr-2 px-3 py-1 bg-yellow-500 text-white rounded hover:bg-yellow-600 text-sm"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => deleteUser(user.id)}
                    className="px-3 py-1 bg-red-500 text-white rounded hover:bg-red-600 text-sm"
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
            {users.length === 0 && (
              <tr>
                <td colSpan={4} className="p-3 text-center text-gray-500">No users yet</td>
              </tr>
            )}
          </tbody>
        </table>
      )}

      {editingUser && (
        <div className="fixed inset-0 bg-black bg-opacity-40 flex items-center justify-center">
          <form onSubmit={updateUser} className="bg-white p-6 rounded shadow-lg w-80">
            <h2 className="text-lg font-semibold mb-4">Edit User #{editingUser.id}</h2>
            <input
              className="w-full border rounded px-3 py-2 mb-3"
              placeholder="Name"
              value={editName}
              onChange={e => setEditName(e.target.value)}
            />
            <input
              className="w-full border rounded px-3 py-2 mb-4"
              placeholder="Email"
              value={editEmail}
              onChange={e => setEditEmail(e.target.value)}
            />
            <div className="flex gap-2 justify-end">
              <button
                type="button"
                onClick={() => setEditingUser(null)}
                className="px-4 py-2 border rounded hover:bg-gray-100"
              >
                Cancel
              </button>
              <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">
                Save
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  )
}

export default App
"}

